INSERT INTO `ability` VALUES (0,'Nothing','Nothing'),(1,'Analytic','Strengthens moves to 1.3× their power when moving last'),(2,'Big Pecks','Protects against Defense drops.'),(3,'Contrary','Inverts stat changes.'),(4,'Cursed Body','Has a 30% chance of Disabling any move that hits the Pokémon.'),(5,'Defeatist','Halves Attack and Special Attack at 50% max HP or less.'),(6,'Defiant','Raises Attack two stages upon having any stat lowered.'),(7,'Flare Boost','Increases Special Attack to 1.5× when burned.'),(8,'Friend Guard','Decreases all direct damage taken by friendly Pokémon to 0.75×.'),(9,'Harvest','Has a 50% chance of restoring a used Berry after each turn if the Pokémon has held no items in the meantime.'),(10,'Healer','Has a 30% chance of curing each adjacent ally of any major status ailment after each turn.'),(11,'Heavy Metal','Doubles the Pokémons weight.'),(12,'Illusion','Takes the appearance of the last conscious party Pokémon upon being sent out until hit by a damaging move.'),(13,'Imposter','Transforms upon entering battle.'),(14,'Infiltrator','Bypasses light screen, reflect, and safeguard.'),(15,'Iron Barbs','Damages attacking Pokémon for 1/8 their max HP on contact.'),(16,'Justified','Raises Attack one stage upon taking damage from a dark move.'),(17,'Light Metal','Halves the Pokémons weight.'),(18,'Magic Bounce','Reflects most non-damaging moves back at their user.'),(19,'Moody','Raises a random stat two stages and lowers another one stage after each turn.'),(20,'Moxie','Raises Attack one stage upon KOing a Pokémon.'),(21,'Multiscale','Halves damage taken from full HP.'),(22,'Mummy','Changes attacking Pokémons abilities to Mummy on contact.'),(23,'Overcoat','Protects against damage from weather.'),(24,'Pickpocket','Steals attacking Pokémons held items on contact.'),(25,'Poison Touch','Has a 30% chance of poisoning target Pokémon upon contact.'),(26,'Prankster','Raises non-damaging moves priority by one stage.'),(27,'Sand Force','Strengthens rock, ground, and steel moves to 1.3× their power during a sandstorm. Protects against sandstorm damage.'),(28,'Sand Rush','Doubles Speed during a sandstorm. Protects against sandstorm damage.'),(29,'Sap Sipper','Absorbs grass moves, raising Attack one stage.'),(30,'Sheer Force','Strengthens moves with extra effects to 1.3× their power, but prevents their extra effects.'),(31,'Telepathy','Protects against friendly Pokémons damaging moves.'),(32,'Teravolt','Bypasses targets abilities if they could hinder or prevent moves.'),(33,'Toxic Boost','Increases Attack to 1.5× when poisoned.'),(34,'Turboblaze','Bypasses targets abilities if they could hinder or prevent moves.'),(35,'Unnerve','Prevents opposing Pokémon from eating held Berries.'),(36,'Victory Star','Increases moves accuracy to 1.1× for friendly Pokémon.'),(37,'Weak Armor','Raises Speed and lowers Defense by one stage each upon being hit by a physical move.'),(38,'Wonder Skin','Lowers incoming non-damaging moves base accuracy to exactly 50%.'),(39,'Zen Mode','Changes darmanitans form after each turn depending on its HP: Zen Mode below 50% max HP, and Standard Mode otherwise.'),(40,'Air Lock','Negates the effects of weather.'),(41,'Arena Trap','Prevents opposing Pokémon from fleeing or switching out.'),(42,'Battle Armor','Protects against critical hits.'),(43,'Blaze','Powers up Fire-type moves when HP is low.'),(44,'Cacophony','Grants immunity to sound-based moves.'),(45,'Chlorophyll','Doubles Speed in harsh sunlight.'),(46,'Clear Body','Prevents other Pokémon from lowering stats.'),(47,'Cloud Nine','Negates the effects of weather.'),(48,'Color Change','Changes type to match the move that hit it.'),(49,'Compound Eyes','Increases move accuracy by 30%.'),(50,'Cute Charm','May infatuate Pokémon that make contact.'),(51,'Damp','Prevents Self-Destruct and Explosion.'),(52,'Drizzle','Summons rain upon entering battle.'),(53,'Drought','Summons harsh sunlight upon entering battle.'),(54,'Early Bird','Wakes from sleep twice as fast.'),(55,'Effect Spore','May inflict poison, paralysis, or sleep on contact.'),(56,'Flame Body','May burn Pokémon that make contact.'),(57,'Flash Fire','Grants immunity to Fire-type moves and boosts Fire attacks.'),(58,'Forecast','Changes form according to weather conditions.'),(59,'Guts','Boosts Attack when affected by a status condition.'),(60,'Huge Power','Doubles the Pokémons Attack stat.'),(61,'Hustle','Boosts Attack but lowers physical move accuracy.'),(62,'Hyper Cutter','Prevents Attack reduction.'),(63,'Illuminate','Raises the likelihood of encountering wild Pokémon.'),(64,'Immunity','Prevents poisoning.'),(65,'Inner Focus','Prevents flinching.'),(66,'Insomnia','Prevents sleep.'),(67,'Intimidate','Lowers opponents Attack upon entering battle.'),(68,'Keen Eye','Prevents accuracy reduction.'),(69,'Levitate','Grants immunity to Ground-type moves.'),(70,'Lightning Rod','Draws Electric-type moves and grants immunity.'),(71,'Limber','Prevents paralysis.'),(72,'Liquid Ooze','Damages opponents using draining moves.'),(73,'Magma Armor','Prevents freezing.'),(74,'Magnet Pull','Prevents Steel-type Pokémon from escaping.'),(75,'Marvel Scale','Boosts Defense when affected by a status condition.'),(76,'Minus','Boosts Special Attack when paired with Plus.'),(77,'Natural Cure','Removes status conditions upon switching out.'),(78,'Oblivious','Prevents infatuation and taunting.'),(79,'Overgrow','Powers up Grass-type moves when HP is low.'),(80,'Own Tempo','Prevents confusion.'),(81,'Pickup','May pick up an item after battle.'),(82,'Plus','Boosts Special Attack when paired with Minus.'),(83,'Poison Point','May poison Pokémon that make contact.'),(84,'Pressure','Raises opponents PP usage by 1.'),(85,'Pure Power','Doubles the Pokémons Attack stat.'),(86,'Rain Dish','Restores HP during rain.'),(87,'Rock Head','Prevents recoil damage.'),(88,'Rough Skin','Damages Pokémon that make contact.'),(89,'Run Away','Allows guaranteed escape from wild battles.'),(90,'Sand Stream','Summons a sandstorm upon entering battle.'),(91,'Sand Veil','Raises evasion during a sandstorm.'),(92,'Serene Grace','Doubles the chance of additional move effects.'),(93,'Shadow Tag','Prevents opposing Pokémon from fleeing or switching out.'),(94,'Shed Skin','May heal status conditions each turn.'),(95,'Shell Armor','Protects against critical hits.'),(96,'Shield Dust','Blocks additional effects from moves.'),(97,'Soundproof','Grants immunity to sound-based moves.'),(98,'Speed Boost','Raises Speed by one stage every turn.'),(99,'Static','May paralyze Pokémon that make contact.'),(100,'Stench','May cause opponents to flinch.'),(101,'Sticky Hold','Prevents held items from being stolen or removed.'),(102,'Sturdy','Prevents one-hit KO moves from affecting the Pokémon.'),(103,'Suction Cups','Prevents forced switching.'),(104,'Swarm','Powers up Bug-type moves when HP is low.'),(105,'Swift Swim','Doubles Speed during rain.'),(106,'Synchronize','Passes poison, paralysis, or burn to the attacker.'),(107,'Thick Fat','Halves damage from Fire and Ice-type moves.'),(108,'Torrent','Powers up Water-type moves when HP is low.'),(109,'Trace','Copies an opponents Ability upon entering battle.'),(110,'Truant','Can only act every other turn.'),(111,'Vital Spirit','Prevents sleep.'),(112,'Volt Absorb','Restores HP when hit by Electric-type moves.'),(113,'Water Absorb','Restores HP when hit by Water-type moves.'),(114,'Water Veil','Prevents burns.'),(115,'White Smoke','Prevents stat reductions by opponents.'),(116,'Wonder Guard','Only super-effective moves can damage the Pokémon.'),(117,'Adaptability','Increases the same-type attack bonus.'),(118,'Aftermath','Damages the attacker when knocked out by contact.'),(119,'Anger Point','Maximizes Attack when hit by a critical hit.'),(120,'Anticipation','Warns of dangerous opposing moves.'),(121,'Bad Dreams','Damages sleeping opposing Pokémon each turn.'),(122,'Download','Raises Attack or Special Attack depending on the opponents defenses.'),(123,'Dry Skin','Restores HP in rain and from Water-type moves, but loses HP in sunlight.'),(124,'Filter','Reduces damage from super-effective moves.'),(125,'Flower Gift','Boosts allies Attack and Special Defense in harsh sunlight.'),(126,'Forewarn','Reveals an opponents strongest move.'),(127,'Frisk','Reveals an opponents held item.'),(128,'Gluttony','Consumes held Berries earlier than usual.'),(129,'Heatproof','Reduces damage from Fire-type moves and burns.'),(130,'Honey Gather','May gather Honey after battle.'),(131,'Ice Body','Restores HP during hail.'),(132,'Iron Fist','Boosts the power of punching moves.'),(133,'Klutz','Prevents the use of held items.'),(134,'Leaf Guard','Prevents status conditions in harsh sunlight.'),(135,'Mold Breaker','Moves ignore the targets Ability if it would interfere.'),(136,'Motor Drive','Raises Speed when hit by an Electric-type move.'),(137,'Mountaineer','Prevents damage from Rock-type moves upon entering battle.'),(138,'Multitype','Changes type based on the held Plate.'),(139,'No Guard','All moves used by and against the Pokémon hit without fail.'),(140,'Normalize','Converts all moves into Normal-type moves.'),(141,'Poison Heal','Restores HP when poisoned instead of taking damage.'),(142,'Quick Feet','Raises Speed when affected by a status condition.'),(143,'Reckless','Boosts moves that cause recoil damage.'),(144,'Rivalry','Deals more damage to Pokémon of the same gender.'),(145,'Scrappy','Allows Normal and Fighting-type moves to hit Ghost-types.'),(146,'Simple','Doubles the effect of stat changes.'),(147,'Skill Link','Multi-hit moves always hit the maximum number of times.'),(148,'Slow Start','Halves Attack and Speed for the first five turns.'),(149,'Sniper','Increases the damage dealt by critical hits.'),(150,'Snow Cloak','Raises evasion during hail.'),(151,'Snow Warning','Summons hail upon entering battle.'),(152,'Solar Power','Boosts Special Attack in sunlight but loses HP each turn.'),(153,'Solid Rock','Reduces damage from super-effective moves.'),(154,'Stall','Makes the Pokémon move last in its priority bracket.'),(155,'Steadfast','Raises Speed after flinching.'),(156,'Storm Drain','Draws in Water-type moves and grants immunity.'),(157,'Super Luck','Raises the critical-hit ratio of moves.'),(158,'Tangled Feet','Raises evasion while confused.'),(159,'Technician','Boosts weaker moves with 60 power or less.'),(160,'Tinted Lens','Increases the power of not very effective moves.'),(161,'Unaware','Ignores opponents stat changes when attacking.'),(162,'Unburden','Doubles Speed after the held item is consumed.'),(163,'Magic Guard','Prevents all indirect damage.');
